<?php $pageTitle='Latest Updates';require_once __DIR__.'/functions.php';$items=db()->query("SELECT * FROM updates ORDER BY id DESC")->fetchAll();include 'includes/header.php';?><section class="page-head"><div class="container"><h1>Latest Updates</h1><p class="muted">Announcements published from Admin.</p></div></section><section class="section" style="padding-top:10px"><div class="container list"><?php if(!$items):?><div class="panel"><h3>No updates yet.</h3></div><?php endif;?><?php foreach($items as $r):?><div class="resource"><div><h3><?=e($r['title'])?></h3><p class="muted"><?=nl2br(e($r['description']))?></p></div><span class="meta"><span><?=date('d M Y',strtotime($r['created_at']))?></span></span></div><?php endforeach;?></div></section><?php include 'includes/footer.php';?>
